{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table izf-wh.maplemonk.izf_returns_consolidated_intermediate as select e.reference_code ,e.saleorderitemcode ,e.ORDER_ID ,Upper(e.order_status) as order_status ,cast(e.ORDER_DATE as datetime) AS Order_Date ,cast(DELIVERED_DATE as datetime) as Delivered_Date ,UPPER(e.marketplace) AS marketplace ,UPPER(e.marketplace) AS MARKETING_CHANNEL ,UPPER(e.marketplace) AS SOURCE ,UPPER(e.PRODUCT_NAME_final) AS PRODUCT_NAME ,e.SKU ,e.sku as commonsku ,e.SKU_STYLE ,e.SKU_SIZE ,UPPER(e.product_category) AS product_category ,UPPER(e.product_sub_category) AS product_sub_category ,e.quantity as order_quantity ,UPPER(e.CITY) AS City ,UPPER(e.STATE) AS State ,e.pincode ,UPPER(e.COURIER) AS Shipping_Courier ,e.awb ,e.name AS NAME ,e.email AS EMAIL ,cast(null as string) as return_request_number ,cast(return_initiated_date as datetime) as original_return_request_date ,cast(null as int64) as no_of_return_requests_initiated ,cast(null as array<string>) as list_of_pickup_couriers_assigned ,cast(null as datetime) as return_approved_date ,cast(null as datetime) as return_refunded_at ,cast(null as datetime) as return_inspected_date ,cast(r.return_date as datetime) as return_date ,case when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'Approved\' else null end as return_approval_status ,case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r.seller_return_reason) like \'%cancel%\' then \'RTO\' when coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) = 1 then \'return\' else null end as return_request_type ,case when lower(r.return_type) like \'%courier%\' or lower(r.seller_return_reason) like \'%rto%\' or lower(r.seller_return_reason) like \'%cancel%\' then \'RTO\' when lower(r.return_type) like \'%customer%\' then \'return\' when lower(r.channel_return_reason) like \'%lost%\' then \'lost\' else cast(null as string) end as return_type ,coalesce((case when Return_Initiated_Date is not null then 1 end),e.return_flag) as return_flag ,r.RETURNED_QUANTITY as TOTAL_RETURNED_QUANTITY ,coalesce(r.channel_return_reason,r.seller_return_reason) as return_reason ,e.Payment_mode ,e.selling_price ,r.PRODUCT_NAME as returned_product_name ,REGEXP_EXTRACT(r.sku, r\'_([^_]+)$\') as returned_product_variant ,r.SKU as returned_sku ,r.Total_Credit_Note_Amount as TOTAL_RETURN_AMOUNT ,case when e.return_flag = 1 then e.tax else 0 end as TOTAL_RETURN_TAX ,null as TOTAL_RETURN_AMOUNT_EXCL_TAX ,r.saleorderitemcode as returned_item_saleorderitemcode ,e.order_status as oms_order_status ,CASE WHEN e.pincode LIKE \'1%\' OR e.pincode LIKE \'2%\' THEN \'North Region\' WHEN e.pincode LIKE \'3%\' OR e.pincode LIKE \'4%\' THEN \'West Region\' WHEN e.pincode LIKE \'5%\' OR e.pincode LIKE \'6%\' THEN \'South Region\' WHEN e.pincode LIKE \'7%\' OR e.pincode LIKE \'8%\' THEN \'East Region\' ELSE NULL END AS region ,DATE_DIFF(date(return_initiated_date), date(Delivered_Date), DAY) AS days_from_delivery ,case when upper(e.sku) like \'B%\' then \'BASIXX\' else \'IZF\' end as brand from maplemonk.izf_sales_consolidated e left join maplemonk.easyecom_izf_all_returns r on e.reference_code = r.reference_code and e.saleorderitemcode = r.saleorderitemcode ; CREATE TEMP TABLE Returns_Data AS WITH returns_daily as ( select * from izf-wh.maplemonk.izf_returns_consolidated ), calendar_dates as ( SELECT date_day FROM UNNEST(GENERATE_DATE_ARRAY(DATE_TRUNC(CURRENT_DATE(), YEAR),CURRENT_DATE())) AS date_day ), date_wise_sku as ( select distinct d.date_day, sku_style, sku from returns_daily r1 left join calendar_dates d on 1=1 ), returns_45_15 as ( select d.date_day return_date, sku_style, sku, ( SELECT SUM(case when lower(r2.return_type) like \'%return%\' then IFNULL(r2.TOTAL_RETURNED_QUANTITY, 0) end) FROM returns_daily r2 WHERE r2.sku_style = d.sku_style AND DATE_DIFF(cast(d.date_day as date),cast(r2.order_date as date),day) BETWEEN 15 and 44 ) AS RETURNED_QUANTITY_BTW_15_45_DAYS, ( SELECT SUM(case when lower(r2.return_type) like \'%rto%\' then IFNULL(r2.TOTAL_RETURNED_QUANTITY, 0) end) FROM returns_daily r2 WHERE r2.sku_style = d.sku_style AND DATE_DIFF(cast(d.date_day as date),cast(r2.order_date as date),day) BETWEEN 15 and 44 ) AS RTO_QUANTITY_BTW_15_45_DAYS, ( SELECT SUM(IFNULL(r2.order_quantity, 0)) FROM returns_daily r2 WHERE r2.sku_style = d.sku_style AND DATE_DIFF(cast(d.date_day as date),cast(r2.order_date as date),day) BETWEEN 15 and 44 ) AS SOLD_QUANTITY_BTW_15_45_DAYS from date_wise_sku d ) select return_date, sku, sku_style, RETURNED_QUANTITY_BTW_15_45_DAYS, RTO_QUANTITY_BTW_15_45_DAYS, SOLD_QUANTITY_BTW_15_45_DAYS from returns_45_15 r where sku is not null and sku <> \'\' ; Create or replace table izf-wh.maplemonk.izf_returns_consolidated as select rc.*, rd.RETURNED_QUANTITY_BTW_15_45_DAYS, rd.RTO_QUANTITY_BTW_15_45_DAYS, rd.SOLD_QUANTITY_BTW_15_45_DAYS from izf-wh.maplemonk.izf_returns_consolidated_intermediate rc left join Returns_Data rd ON lower(RD.sku) = lower(rc.sku) AND CAST(rc.order_date AS DATE) = CAST(rd.return_date AS DATE) AND lower(Rc.sku_style) = lower(rd.sku_style); CREATE OR REPLACE TABLE izf-wh.maplemonk.izf_returns_count_data as WITH orders as ( SELECT LAST_DAY(date(order_date), MONTH) as order_month, DATE_TRUNC(order_Date, MONTH) as month_first_date, date(order_date) as order_date, marketplace, sku_style as style, count(distinct reference_code) as orders_for_the_month, COUNT(DISTINCT CASE WHEN (return_flag = 1 and lower(return_request_type) = \'return\') THEN reference_code END) AS total_returned_orders_for_orders_of_month, sum(case when (return_flag=1 and lower(return_request_type) = \'return\') then 1 else 0 end) as total_returned_items_for_orders_of_month, sum(case when (return_flag=1 and lower(return_request_type) = \'return\') then TOTAL_RETURNED_QUANTITY else 0 end) as total_returned_quantity_for_orders_of_month, count(*) as total_order_items_for_the_month, sum(order_quantity) as total_order_quantity_for_the_month, sum(selling_price) as total_sales FROM izf-wh.maplemonk.izf_returns_consolidated GROUP BY order_month,month_first_date, order_date,marketplace,sku_style ), returns as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(original_return_request_date) as return_date, marketplace, sku_style as style, COUNT(*) as total_returned_items_received_in_month, count(distinct reference_code) as returned_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as returned_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_sales FROM izf-wh.maplemonk.izf_returns_consolidated WHERE return_flag = 1 and lower(return_request_type) = \'return\' and original_return_request_date is not null GROUP BY return_month,return_date,marketplace,sku_style ), rto as ( SELECT LAST_DAY(DATE(return_date), MONTH) as return_month, date(return_date) as return_date, marketplace, sku_style as style, COUNT(*) as total_rto_items_received_in_month, count(distinct reference_code) as rto_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as rto_quantity_received_in_month, sum(TOTAL_RETURN_AMOUNT) as total_returned_rto_sales FROM izf-wh.maplemonk.izf_returns_consolidated WHERE return_flag = 1 and lower(return_request_type) = \'rto\' and original_return_request_date is not null GROUP BY return_month,return_date,marketplace,sku_style ) SELECT o.month_first_date, o.marketplace, o.style, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, rto.total_rto_items_received_in_month, rto.rto_orders_received_in_month, rto.rto_quantity_received_in_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace and r.style = o.style LEFT JOIN rto ON rto.return_date = o.order_date and rto.marketplace = o.marketplace and rto.style = o.style LEFT JOIN returns rd45 ON rd45.return_date BETWEEN (r.return_date - INTERVAL 45 DAY) AND (r.return_date - INTERVAL 15 DAY) and rd45.marketplace = o.marketplace and rd45.style = o.style order by order_date desc;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            